     1→#include "vm.h"
     2→#include "isa.h"
     3→#include <stdlib.h>
     4→#include <stdio.h>
     5→
     6→/* VM 초기화 */
     7→void vm_init(VM* vm) {
     8→    memset(vm->registers, 0, sizeof(vm->registers));
     9→    memset(vm->memory, 0, sizeof(vm->memory));
    10→    memset(vm->stack, 0, sizeof(vm->stack));
    11→    vm->sp = -1;
    12→    vm->ip = 0;
    13→    vm->try_depth = 0;
    14→    memset(&vm->flags, 0, sizeof(vm->flags));
    15→    memset(&vm->last_error, 0, sizeof(vm->last_error));
    16→}
    17→
    18→/* 스택에 값 푸시 */
    19→void vm_push(VM* vm, int32_t value) {
    20→    if (vm->sp >= STACK_SIZE - 1) {
    21→        vm_raise(vm, "StackOverflow", "Stack overflow", 1);
    22→        return;
    23→    }
    24→    vm->stack[++vm->sp] = value;
    25→}
    26→
    27→/* 스택에서 값 팝 */
    28→int32_t vm_pop(VM* vm) {
    29→    if (vm->sp < 0) {
    30→        vm_raise(vm, "StackUnderflow", "Stack underflow", 2);
    31→        return 0;
    32→    }
    33→    return vm->stack[vm->sp--];
    34→}
    35→
    36→/* 예외 발생 */
    37→void vm_raise(VM* vm, const char* type, const char* msg, int code) {
    38→    strncpy(vm->last_error.type, type, 63);
    39→    strncpy(vm->last_error.message, msg, 255);
    40→    vm->last_error.code = code;
    41→    printf("[EXCEPTION] %s: %s (code: %d)\n", type, msg, code);
    42→    longjmp(vm->jump_buffer, 1);
    43→}
    44→
    45→/* 플래그 업데이트 */
    46→void vm_update_flags(VM* vm, int32_t value) {
    47→    vm->flags.Z = (value == 0);
    48→    vm->flags.S = (value < 0);
    49→    vm->flags.C = 0;  /* 간단하게 설정 */
    50→}
    51→
    52→/* 비교 연산 및 플래그 설정 */
    53→void vm_cmp(VM* vm, int32_t a, int32_t b) {
    54→    int32_t diff = a - b;
    55→    vm->flags.E = (a == b);
    56→    vm->flags.L = (a < b);
    57→    vm->flags.Z = (diff == 0);
    58→    vm->flags.S = (diff < 0);
    59→}
    60→
    61→/* VM 상태 출력 (디버깅용) */
    62→void vm_print_state(VM* vm) {
    63→    printf("\n=== VM State ===\n");
    64→    printf("IP: %d, SP: %d\n", vm->ip, vm->sp);
    65→    printf("Registers: ");
    66→    for (int i = 0; i < 8; i++) {
    67→        printf("r%d=%d ", i, vm->registers[i]);
    68→    }
    69→    printf("\nFlags: Z=%d C=%d S=%d E=%d L=%d\n",
    70→           vm->flags.Z, vm->flags.C, vm->flags.S, vm->flags.E, vm->flags.L);
    71→    printf("================\n\n");
    72→}
    73→
    74→/* VM 실행 */
    75→void vm_run(VM* vm, uint8_t* bytecode, int length) {
    76→    int call_stack[256];  /* 함수 호출 스택 */
    77→    int call_depth = 0;
    78→
    79→    /* Try-catch 구조 설정 */
    80→    if (setjmp(vm->jump_buffer) != 0) {
    81→        printf("Exception caught: %s\n", vm->last_error.message);
    82→        return;
    83→    }
    84→
    85→    vm->ip = 0;
    86→    while (vm->ip < length) {
    87→        uint8_t byte = bytecode[vm->ip++];
    88→        OpCode op = (OpCode)byte;
    89→
    90→        switch (op) {
    91→            case OP_NOP:
    92→                /* No operation */
    93→                break;
    94→
    95→            case OP_HALT:
    96→                printf("Program halted\n");
    97→                return;
    98→
    99→            case OP_MOV: {
   100→                /* MOV dest, src */
   101→                uint8_t dest = bytecode[vm->ip++];
   102→                uint8_t src = bytecode[vm->ip++];
   103→                vm->registers[dest] = vm->registers[src];
   104→                break;
   105→            }
   106→
   107→            case OP_ADD: {
   108→                /* ADD dest, src1, src2 */
   109→                uint8_t dest = bytecode[vm->ip++];
   110→                uint8_t src1 = bytecode[vm->ip++];
   111→                uint8_t src2 = bytecode[vm->ip++];
   112→                int32_t result = vm->registers[src1] + vm->registers[src2];
   113→                vm->registers[dest] = result;
   114→                vm_update_flags(vm, result);
   115→                break;
   116→            }
   117→
   118→            case OP_SUB: {
   119→                /* SUB dest, src1, src2 */
   120→                uint8_t dest = bytecode[vm->ip++];
   121→                uint8_t src1 = bytecode[vm->ip++];
   122→                uint8_t src2 = bytecode[vm->ip++];
   123→                int32_t result = vm->registers[src1] - vm->registers[src2];
   124→                vm->registers[dest] = result;
   125→                vm_update_flags(vm, result);
   126→                break;
   127→            }
   128→
   129→            case OP_MUL: {
   130→                /* MUL dest, src1, src2 */
   131→                uint8_t dest = bytecode[vm->ip++];
   132→                uint8_t src1 = bytecode[vm->ip++];
   133→                uint8_t src2 = bytecode[vm->ip++];
   134→                int32_t result = vm->registers[src1] * vm->registers[src2];
   135→                vm->registers[dest] = result;
   136→                vm_update_flags(vm, result);
   137→                break;
   138→            }
   139→
   140→            case OP_DIV: {
   141→                /* DIV dest, src1, src2 */
   142→                uint8_t dest = bytecode[vm->ip++];
   143→                uint8_t src1 = bytecode[vm->ip++];
   144→                uint8_t src2 = bytecode[vm->ip++];
   145→                if (vm->registers[src2] == 0) {
   146→                    vm_raise(vm, "DivideByZero", "Division by zero", 3);
   147→                }
   148→                int32_t result = vm->registers[src1] / vm->registers[src2];
   149→                vm->registers[dest] = result;
   150→                vm_update_flags(vm, result);
   151→                break;
   152→            }
   153→
   154→            case OP_LOAD: {
   155→                /* LOAD reg, [addr] */
   156→                uint8_t reg = bytecode[vm->ip++];
   157→                uint16_t addr = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   158→                vm->ip += 2;
   159→                if (addr >= MEM_SIZE) {
   160→                    vm_raise(vm, "OutOfBounds", "Memory access out of bounds", 4);
   161→                }
   162→                vm->registers[reg] = *(int32_t*)(vm->memory + addr);
   163→                break;
   164→            }
   165→
   166→            case OP_STORE: {
   167→                /* STORE [addr], reg */
   168→                uint16_t addr = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   169→                vm->ip += 2;
   170→                uint8_t reg = bytecode[vm->ip++];
   171→                if (addr >= MEM_SIZE) {
   172→                    vm_raise(vm, "OutOfBounds", "Memory access out of bounds", 4);
   173→                }
   174→                *(int32_t*)(vm->memory + addr) = vm->registers[reg];
   175→                break;
   176→            }
   177→
   178→            case OP_CMP: {
   179→                /* CMP reg1, reg2 */
   180→                uint8_t reg1 = bytecode[vm->ip++];
   181→                uint8_t reg2 = bytecode[vm->ip++];
   182→                vm_cmp(vm, vm->registers[reg1], vm->registers[reg2]);
   183→                break;
   184→            }
   185→
   186→            case OP_JMP: {
   187→                /* JMP addr */
   188→                uint16_t addr = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   189→                vm->ip = addr;
   190→                break;
   191→            }
   192→
   193→            case OP_JMP_IF: {
   194→                /* JMP_IF cond, addr */
   195→                uint8_t cond = bytecode[vm->ip++];
   196→                uint16_t addr = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   197→                vm->ip += 2;
   198→                int should_jump = 0;
   199→                switch (cond) {
   200→                    case 0: should_jump = vm->flags.Z; break;     /* Z */
   201→                    case 1: should_jump = !vm->flags.Z; break;    /* NZ */
   202→                    case 2: should_jump = vm->flags.E; break;     /* E */
   203→                    case 3: should_jump = !vm->flags.E; break;    /* NE */
   204→                    case 4: should_jump = vm->flags.L; break;     /* L */
   205→                    default: break;
   206→                }
   207→                if (should_jump) {
   208→                    vm->ip = addr;
   209→                }
   210→                break;
   211→            }
   212→
   213→            case OP_PUSH: {
   214→                /* PUSH reg */
   215→                uint8_t reg = bytecode[vm->ip++];
   216→                vm_push(vm, vm->registers[reg]);
   217→                break;
   218→            }
   219→
   220→            case OP_POP: {
   221→                /* POP reg */
   222→                uint8_t reg = bytecode[vm->ip++];
   223→                vm->registers[reg] = vm_pop(vm);
   224→                break;
   225→            }
   226→
   227→            case OP_CALL: {
   228→                /* CALL addr */
   229→                uint16_t addr = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   230→                vm->ip += 2;
   231→                if (call_depth >= 256) {
   232→                    vm_raise(vm, "StackOverflow", "Call stack overflow", 5);
   233→                }
   234→                call_stack[call_depth++] = vm->ip;
   235→                vm->ip = addr;
   236→                break;
   237→            }
   238→
   239→            case OP_RET: {
   240→                /* RET */
   241→                if (call_depth == 0) {
   242→                    vm_raise(vm, "RuntimeError", "Return without call", 6);
   243→                }
   244→                vm->ip = call_stack[--call_depth];
   245→                break;
   246→            }
   247→
   248→            case OP_TRY_BEGIN: {
   249→                /* TRY_BEGIN handler_addr */
   250→                uint16_t handler = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   251→                vm->ip += 2;
   252→                vm->try_depth++;
   253→                printf("Try block started (depth=%d, handler=%d)\n", vm->try_depth, handler);
   254→                break;
   255→            }
   256→
   257→            case OP_TRY_END: {
   258→                /* TRY_END */
   259→                if (vm->try_depth > 0) {
   260→                    vm->try_depth--;
   261→                }
   262→                printf("Try block ended (depth=%d)\n", vm->try_depth);
   263→                break;
   264→            }
   265→
   266→            case OP_RAISE: {
   267→                /* RAISE */
   268→                vm_raise(vm, "UserError", "User-defined exception", 7);
   269→                break;
   270→            }
   271→
   272→            case OP_CATCH: {
   273→                /* CATCH error_reg */
   274→                uint8_t reg = bytecode[vm->ip++];
   275→                /* 에러 코드를 레지스터에 저장 */
   276→                vm->registers[reg] = vm->last_error.code;
   277→                printf("Caught error in register r%d (code=%d)\n", reg, vm->last_error.code);
   278→                break;
   279→            }
   280→
   281→            case OP_FOR_INIT: {
   282→                /* FOR_INIT reg, count */
   283→                uint8_t reg = bytecode[vm->ip++];
   284→                int32_t count = (bytecode[vm->ip] << 24) | (bytecode[vm->ip + 1] << 16) |
   285→                                (bytecode[vm->ip + 2] << 8) | bytecode[vm->ip + 3];
   286→                vm->ip += 4;
   287→                vm->registers[reg] = count;
   288→                break;
   289→            }
   290→
   291→            case OP_FOR_NEXT: {
   292→                /* FOR_NEXT reg, start_addr */
   293→                uint8_t reg = bytecode[vm->ip++];
   294→                uint16_t addr = (bytecode[vm->ip] << 8) | bytecode[vm->ip + 1];
   295→                vm->ip += 2;
   296→                vm->registers[reg]--;
   297→                if (vm->registers[reg] >= 0) {
   298→                    vm->ip = addr;
   299→                }
   300→                break;
   301→            }
   302→
   303→            default:
   304→                printf("Unknown opcode: %d at IP %d\n", op, vm->ip - 1);
   305→                return;
   306→        }
   307→
   308→        /* 디버깅: 상태 출력 (선택적) */
   309→        /* vm_print_state(vm); */
   310→    }
   311→
   312→    printf("Program finished normally\n");
   313→}
