    96→# ================================================================
    97→# Parser 상태 관리
    98→# ================================================================
    99→
   100→fn createParserState(tokens: []) {
   101→  return {
   102→    "tokens": tokens,
   103→    "position": 0
   104→  }
   105→}
   106→
   107→# 현재 토큰 접근
   108→fn currentToken(state: {}) {
   109→  if state["position"] < len(state["tokens"]) {
   110→    return state["tokens"][state["position"]]
   111→  }
   112→  return { "type": "eof", "value": "" }
   113→}
   114→
   115→# 다음 토큰 미리보기
   116→fn peekToken(state: {}, offset: int) {
   117→  pos = state["position"] + offset
   118→  if pos < len(state["tokens"]) {
   119→    return state["tokens"][pos]
   120→  }
   121→  return { "type": "eof", "value": "" }
   122→}
   123→
   124→# 토큰 이동
   125→fn advance(state: {}) {
   126→  state["position"] = state["position"] + 1
   127→  return state
   128→}
   129→
   130→# 토큰 매칭
   131→fn match(state: {}, expectedType: string, expectedValue: string) {
   132→  token = currentToken(state)
   133→  if token["type"] == expectedType and (expectedValue == "" or token["value"] == expectedValue) {
   134→    state = advance(state)
   135→    return { "matched": true, "state": state, "token": token }
   136→  }
   137→  return { "matched": false, "state": state, "token": null }
   138→}
   139→
   140→# ================================================================
   141→# Parse 진입점 (메인 함수)
   142→# ================================================================
   143→
   144→fn parse(tokens: []) {
   145→  state = createParserState(tokens)
   146→  statements = []
   147→
   148→  # 메인 루프: EOF까지 문장 파싱
   149→  while currentToken(state)["type"] != "eof" {
   150→    # 빈 줄 건너뛰기
   151→    if currentToken(state)["type"] == "newline" {
   152→      state = advance(state)
   153→    }
   154→    else {
   155→      stmt = parseStatement(state)
   156→      if stmt != null {
   157→        statements = statements + [stmt]
   158→      }
   159→      state = stmt["_state"]
   160→    }
   161→  }
   162→
   163→  return statements
   164→}
   165→
   166→# ================================================================
   167→# Statement 파싱
   168→# ================================================================
   169→
   170→fn parseStatement(state: {}) {
   171→  token = currentToken(state)
   172→
   173→  # 함수 정의
   174→  if token["type"] == "keyword" and token["value"] == "fn" {
   175→    return parseFunctionDefinition(state)
   176→  }
   177→  # struct 정의
   178→  else if token["type"] == "keyword" and token["value"] == "struct" {
   179→    return parseStructDefinition(state)
   180→  }
   181→  # if 문
   182→  else if token["type"] == "keyword" and token["value"] == "if" {
   183→    return parseIfStatement(state)
   184→  }
   185→  # while 루프
   186→  else if token["type"] == "keyword" and token["value"] == "while" {
   187→    return parseWhileStatement(state)
   188→  }
   189→  # for-in 루프
   190→  else if token["type"] == "keyword" and token["value"] == "for" {
   191→    return parseForInStatement(state)
   192→  }
   193→  # return 문
   194→  else if token["type"] == "keyword" and token["value"] == "return" {
   195→    return parseReturnStatement(state)
   196→  }
   197→  # break 문 (루프 탈출)
   198→  else if token["type"] == "keyword" and token["value"] == "break" {
   199→    state = advance(state)
   200→    node = { "type": "breakStatement" }
   201→    return { "_state": state, "value": node }
   202→  }
   203→  # continue 문 (다음 반복)
   204→  else if token["type"] == "keyword" and token["value"] == "continue" {
   205→    state = advance(state)
   206→    node = { "type": "continueStatement" }
   207→    return { "_state": state, "value": node }
   208→  }
   209→  # match 패턴 매칭
   210→  else if token["type"] == "keyword" and token["value"] == "match" {
   211→    return parseMatchStatement(state)
   212→  }
   213→  # async fn (async 함수 정의)
   214→  else if token["type"] == "keyword" and token["value"] == "async" {
   215→    state = advance(state)
   216→    if currentToken(state)["value"] == "fn" {
   217→      return parseFunctionDefinition(state, true)  # async=true
   218→    }
   219→    return { "_state": state, "error": "Expected 'fn' after 'async'" }
   220→  }
   221→  # 블록
   222→  else if token["type"] == "lbrace" {
   223→    return parseBlockStatement(state)
   224→  }
   225→  # 식 문장
   226→  else {
   227→    return parseExpressionStatement(state)
   228→  }
   229→}
   230→
   231→# 식 문장
   232→fn parseExpressionStatement(state: {}) {
   233→  expr = parseExpression(state)
   234→  state = expr["_state"]
   235→
   236→  # 세미콜론 또는 줄바꿈 선택적
   237→  if currentToken(state)["type"] == "semicolon" {
   238→    state = advance(state)
   239→  }
   240→  else if currentToken(state)["type"] == "newline" {
   241→    state = advance(state)
   242→  }
   243→
   244→  return { "_state": state, "result": expr }
   245→}
   246→
   247→# 함수 정의
   248→fn parseFunctionDefinition(state: {}) {
   249→  # fn 키워드 건너뛰기
   250→  state = advance(state)
   251→
   252→  # 함수 이름
   253→  nameToken = currentToken(state)
   254→  if nameToken["type"] != "identifier" {
   255→    print("Expected identifier after 'fn'")
   256→    return { "_state": state, "result": null }
   257→  }
   258→  funcName = nameToken["value"]
   259→  state = advance(state)
   260→
   261→  # 매개변수 목록
   262→  params = []
   263→  if currentToken(state)["type"] == "lparen" {
   264→    state = advance(state)
   265→
   266→    while currentToken(state)["type"] != "rparen" {
   267→      paramToken = currentToken(state)
   268→      if paramToken["type"] == "identifier" {
   269→        params = params + [paramToken["value"]]
   270→        state = advance(state)
   271→
   272→        # 타입 주석 건너뛰기 (optional)
   273→        if currentToken(state)["type"] == "colon" {
   274→          state = advance(state)
   275→          # 타입 정보 무시
   276→          state = advance(state)
   277→        }
   278→
   279→        # 쉼표
   280→        if currentToken(state)["type"] == "comma" {
   281→          state = advance(state)
   282→        }
   283→      }
   284→      else {
   285→        print("Expected parameter name")
   286→        state = advance(state)
   287→      }
   288→    }
   289→
   290→    state = advance(state)  # rparen
   291→  }
   292→
   293→  # 함수 본문
   294→  body = []
   295→  if currentToken(state)["type"] == "lbrace" {
   296→    blockStmt = parseBlockStatement(state)
   297→    state = blockStmt["_state"]
   298→    body = blockStmt["result"]["statements"]
   299→  }
   300→
   301→  funcDef = createFunctionDefinition(funcName, params, body)
   302→  return { "_state": state, "result": funcDef }
   303→}
   304→
   305→# struct 정의
   306→fn parseStructDefinition(state: {}) {
   307→  # struct 키워드 건너뛰기
   308→  state = advance(state)
   309→
   310→  # struct 이름
   311→  nameToken = currentToken(state)
   312→  if nameToken["type"] != "identifier" {
   313→    print("Expected identifier after 'struct'")
   314→    return { "_state": state, "result": null }
   315→  }
   316→  structName = nameToken["value"]
   317→  state = advance(state)
   318→
   319→  # 필드 정의 ({})
   320→  fields = []
   321→  if currentToken(state)["type"] == "lbrace" {
   322→    state = advance(state)
   323→
   324→    while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   325→      # 필드명
   326→      fieldToken = currentToken(state)
   327→      if fieldToken["type"] == "identifier" {
   328→        fieldName = fieldToken["value"]
   329→        state = advance(state)
   330→
   331→        # 타입 주석 (필수)
   332→        if currentToken(state)["type"] == "colon" {
   333→          state = advance(state)
   334→          typeToken = currentToken(state)
   335→          fieldType = typeToken["value"]
   336→          state = advance(state)
   337→
   338→          # 필드 추가
   339→          fields = fields + [{ "name": fieldName, "type": fieldType }]
   340→        }
   341→
   342→        # 쉼표
   343→        if currentToken(state)["type"] == "comma" {
   344→          state = advance(state)
   345→        }
   346→      }
   347→      else {
   348→        print("Expected field name in struct definition")
   349→        break
   350→      }
   351→    }
   352→
   353→    if currentToken(state)["type"] == "rbrace" {
   354→      state = advance(state)
   355→    }
   356→  }
   357→
   358→  structDef = createStructDefinition(structName, fields)
   359→  return { "_state": state, "result": structDef }
   360→}
   361→
   362→# if 문
   363→fn parseIfStatement(state: {}) {
   364→  # if 키워드 건너뛰기
   365→  state = advance(state)
   366→
   367→  # 조건
   368→  condition = parseExpression(state)
   369→  state = condition["_state"]
   370→
   371→  # then 블록
   372→  thenBlock = parseBlockStatement(state)
   373→  state = thenBlock["_state"]
   374→  thenBranch = thenBlock["result"]["statements"]
   375→
   376→  # else 블록 (optional)
   377→  elseBranch = []
   378→  if currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "else" {
   379→    state = advance(state)
   380→
   381→    elseBlock = parseBlockStatement(state)
   382→    state = elseBlock["_state"]
   383→    elseBranch = elseBlock["result"]["statements"]
   384→  }
   385→
   386→  ifStmt = createIfStatement(condition, thenBranch, elseBranch)
   387→  return { "_state": state, "result": ifStmt }
   388→}
   389→
   390→# match 패턴 매칭
   391→fn parseMatchStatement(state: {}) {
   392→  # match 키워드 건너뛰기
   393→  state = advance(state)
   394→
   395→  # 매칭할 식
   396→  expr = parseExpression(state)
   397→  state = expr["_state"]
   398→
   399→  # arms 수집
   400→  arms = []
   401→
   402→  # 각 arm 파싱 (패턴 => 결과)
   403→  while currentToken(state)["type"] != "keyword" or currentToken(state)["value"] != "end" {
   404→    # 패턴 (숫자, 문자열, 또는 _)
   405→    patternToken = currentToken(state)
   406→    pattern = patternToken["value"]
   407→    state = advance(state)
   408→
   409→    # => 기대
   410→    if currentToken(state)["type"] != "arrow" {
   411→      state = advance(state)  # skip
   412→    } else {
   413→      state = advance(state)
   414→    }
   415→
   416→    # 결과 식 파싱
   417→    result = parseExpression(state)
   418→    state = result["_state"]
   419→
   420→    arm = { "pattern": pattern, "result": result["value"] }
   421→    arms = push(arms, arm)
   422→
   423→    # 쉼표 또는 end
   424→    if currentToken(state)["type"] == "comma" {
   425→      state = advance(state)
   426→    }
   427→  }
   428→
   429→  # end 키워드 건너뛰기
   430→  if currentToken(state)["value"] == "end" {
   431→    state = advance(state)
   432→  }
   433→
   434→  matchStmt = { "type": "matchStatement", "expr": expr["value"], "arms": arms }
   435→  return { "_state": state, "result": matchStmt }
   436→}
   437→
   438→# while 루프
   439→fn parseWhileStatement(state: {}) {
   440→  # while 키워드 건너뛰기
   441→  state = advance(state)
   442→
   443→  # 조건
   444→  condition = parseExpression(state)
   445→  state = condition["_state"]
   446→
   447→  # 루프 본문
   448→  body = []
   449→  if currentToken(state)["type"] == "lbrace" {
   450→    blockStmt = parseBlockStatement(state)
   451→    state = blockStmt["_state"]
   452→    body = blockStmt["result"]["statements"]
   453→  }
   454→
   455→  whileStmt = createWhileStatement(condition, body)
   456→  return { "_state": state, "result": whileStmt }
   457→}
   458→
   459→# for-in 루프
   460→fn parseForInStatement(state: {}) {
   461→  # for 키워드 건너뛰기
   462→  state = advance(state)
   463→
   464→  # 루프 변수
   465→  varToken = currentToken(state)
   466→  if varToken["type"] != "identifier" {
   467→    print("Expected identifier after 'for'")
   468→    return { "_state": state, "result": null }
   469→  }
   470→  varName = varToken["value"]
   471→  state = advance(state)
   472→
   473→  # in 키워드
   474→  if currentToken(state)["type"] != "keyword" or currentToken(state)["value"] != "in" {
   475→    print("Expected 'in' in for-in loop")
   476→    return { "_state": state, "result": null }
   477→  }
   478→  state = advance(state)
   479→
   480→  # 반복 가능한 식 (배열 또는 range)
   481→  iterable = parseExpression(state)
   482→  state = iterable["_state"]
   483→
   484→  # 루프 본문
   485→  body = []
   486→  if currentToken(state)["type"] == "lbrace" {
   487→    blockStmt = parseBlockStatement(state)
   488→    state = blockStmt["_state"]
   489→    body = blockStmt["result"]["statements"]
   490→  }
   491→
   492→  forInStmt = createForInStatement(varName, iterable, body)
   493→  return { "_state": state, "result": forInStmt }
   494→}
   495→
   496→# return 문
   497→fn parseReturnStatement(state: {}) {
   498→  # return 키워드 건너뛰기
   499→  state = advance(state)
   500→
   501→  # 반환값 (optional)
   502→  value = null
   503→  if currentToken(state)["type"] != "newline" and currentToken(state)["type"] != "eof" {
   504→    exprResult = parseExpression(state)
   505→    state = exprResult["_state"]
   506→    value = exprResult
   507→  }
   508→
   509→  retStmt = createReturnStatement(value)
   510→  return { "_state": state, "result": retStmt }
   511→}
   512→
   513→# 블록 문
   514→fn parseBlockStatement(state: {}) {
   515→  if currentToken(state)["type"] != "lbrace" {
   516→    print("Expected '{'")
   517→    return { "_state": state, "result": { "type": "blockStatement", "statements": [] } }
   518→  }
   519→
   520→  state = advance(state)  # lbrace
   521→  statements = []
   522→
   523→  while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   524→    if currentToken(state)["type"] == "newline" {
   525→      state = advance(state)
   526→    }
   527→    else {
   528→      stmt = parseStatement(state)
   529→      if stmt != null {
   530→        statements = statements + [stmt["result"]]
   531→      }
   532→      state = stmt["_state"]
   533→    }
   534→  }
   535→
   536→  if currentToken(state)["type"] == "rbrace" {
   537→    state = advance(state)
   538→  }
   539→
   540→  blockStmt = createBlockStatement(statements)
   541→  return { "_state": state, "result": blockStmt }
   542→}
   543→
   544→# ================================================================
   545→# Expression 파싱 (우선순위 기반)
   546→# ================================================================
   547→
   548→# 최상위 (낮은 우선순위)
   549→fn parseExpression(state: {}) {
   550→  return parseAssignment(state)
   551→}
   552→
   553→# 할당 (= 연산자)
   554→fn parseAssignment(state: {}) {
   555→  expr = parseOr(state)
   556→  state = expr["_state"]
   557→
   558→  if currentToken(state)["type"] == "equals" {
   559→    state = advance(state)
   560→
   561→    # 좌변이 identifier, arrayAccess, 또는 memberAccess
   562→    if expr["type"] == "identifier" {
   563→      value = parseAssignment(state)
   564→      state = value["_state"]
   565→
   566→      assignment = createAssignment(expr["name"], value)
   567→      return { "_state": state, "result": assignment }
   568→    }
   569→    else if expr["type"] == "arrayAccess" {
   570→      value = parseAssignment(state)
   571→      state = value["_state"]
   572→
   573→      assignment = createArrayAssignment(expr["array"], expr["index"], value)
   574→      return { "_state": state, "result": assignment }
   575→    }
   576→    else if expr["type"] == "memberAccess" {
   577→      value = parseAssignment(state)
   578→      state = value["_state"]
   579→
   580→      assignment = createMemberAssignment(expr["object"], expr["property"], value)
   581→      return { "_state": state, "result": assignment }
   582→    }
   583→  }
   584→
   585→  return { "_state": state, "result": expr }
   586→}
   587→
   588→# OR 연산자 (||)
   589→fn parseOr(state: {}) {
   590→  left = parseAnd(state)
   591→  state = left["_state"]
   592→
   593→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "||" {
   594→    state = advance(state)
   595→    right = parseAnd(state)
   596→    state = right["_state"]
   597→
   598→    left = createBinaryOp(left, "||", right)
   599→  }
   600→
   601→  return { "_state": state, "result": left }
   602→}
   603→
   604→# AND 연산자 (&&)
   605→fn parseAnd(state: {}) {
   606→  left = parseEquality(state)
   607→  state = left["_state"]
   608→
   609→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "&&" {
   610→    state = advance(state)
   611→    right = parseEquality(state)
   612→    state = right["_state"]
   613→
   614→    left = createBinaryOp(left, "&&", right)
   615→  }
   616→
   617→  return { "_state": state, "result": left }
   618→}
   619→
   620→# 동등성 (==, !=)
   621→fn parseEquality(state: {}) {
   622→  left = parseComparison(state)
   623→  state = left["_state"]
   624→
   625→  while currentToken(state)["type"] == "operator" and
   626→        (currentToken(state)["value"] == "==" or currentToken(state)["value"] == "!=") {
   627→    op = currentToken(state)["value"]
   628→    state = advance(state)
   629→
   630→    right = parseComparison(state)
   631→    state = right["_state"]
   632→
   633→    left = createBinaryOp(left, op, right)
   634→  }
   635→
   636→  return { "_state": state, "result": left }
   637→}
   638→
   639→# 비교 (<, <=, >, >=)
   640→fn parseComparison(state: {}) {
   641→  left = parseAddition(state)
   642→  state = left["_state"]
   643→
   644→  while currentToken(state)["type"] == "operator" and
   645→        (currentToken(state)["value"] == "<" or
   646→         currentToken(state)["value"] == "<=" or
   647→         currentToken(state)["value"] == ">" or
   648→         currentToken(state)["value"] == ">=") {
   649→    op = currentToken(state)["value"]
   650→    state = advance(state)
   651→
   652→    right = parseAddition(state)
   653→    state = right["_state"]
   654→
   655→    left = createBinaryOp(left, op, right)
   656→  }
   657→
   658→  return { "_state": state, "result": left }
   659→}
   660→
   661→# 덧셈 (+, -)
   662→fn parseAddition(state: {}) {
   663→  left = parseMultiplication(state)
   664→  state = left["_state"]
   665→
   666→  while currentToken(state)["type"] == "operator" and
   667→        (currentToken(state)["value"] == "+" or currentToken(state)["value"] == "-") {
   668→    op = currentToken(state)["value"]
   669→    state = advance(state)
   670→
   671→    right = parseMultiplication(state)
   672→    state = right["_state"]
   673→
   674→    left = createBinaryOp(left, op, right)
   675→  }
   676→
   677→  return { "_state": state, "result": left }
   678→}
   679→
   680→# 곱셈 (*, /, %)
   681→fn parseMultiplication(state: {}) {
   682→  left = parseUnary(state)
   683→  state = left["_state"]
   684→
   685→  while currentToken(state)["type"] == "operator" and
   686→        (currentToken(state)["value"] == "*" or
   687→         currentToken(state)["value"] == "/" or
   688→         currentToken(state)["value"] == "%") {
   689→    op = currentToken(state)["value"]
   690→    state = advance(state)
   691→
   692→    right = parseUnary(state)
   693→    state = right["_state"]
   694→
   695→    left = createBinaryOp(left, op, right)
   696→  }
   697→
   698→  return { "_state": state, "result": left }
   699→}
   700→
   701→# 단항 연산 (-, !, &, &mut)
   702→fn parseUnary(state: {}) {
   703→  # await 표현식 처리
   704→  if currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "await" {
   705→    state = advance(state)
   706→    operand = parseUnary(state)
   707→    state = operand["_state"]
   708→    awaitExpr = { "type": "awaitExpression", "operand": operand["result"] }
   709→    return { "_state": state, "result": awaitExpr }
   710→  }
   711→
   712→  if currentToken(state)["type"] == "operator" and
   713→     (currentToken(state)["value"] == "-" or
   714→      currentToken(state)["value"] == "!" or
   715→      currentToken(state)["value"] == "&") {
   716→    op = currentToken(state)["value"]
   717→    state = advance(state)
   718→
   719→    # &mut 처리
   720→    if op == "&" and currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "mut" {
   721→      state = advance(state)
   722→      op = "&mut"
   723→    }
   724→
   725→    operand = parseUnary(state)
   726→    state = operand["_state"]
   727→
   728→    unary = createUnaryOp(op, operand)
   729→    return { "_state": state, "result": unary }
   730→  }
   731→
   732→  return parseCall(state)
   733→}
   734→
   735→# 함수 호출 (()) + 멤버 접근 (.)
   736→fn parseCall(state: {}) {
   737→  expr = parsePrimary(state)
   738→  state = expr["_state"]
   739→
   740→  while true {
   741→    if currentToken(state)["type"] == "lparen" {
   742→      # 함수 호출
   743→      state = advance(state)
   744→      args = []
   745→
   746→      while currentToken(state)["type"] != "rparen" {
   747→        arg = parseExpression(state)
   748→        state = arg["_state"]
   749→        args = args + [arg]
   750→
   751→        if currentToken(state)["type"] == "comma" {
   752→          state = advance(state)
   753→        }
   754→      }
   755→
   756→      state = advance(state)  # rparen
   757→      expr = createCallExpression(expr, args)
   758→    }
   759→    else if currentToken(state)["type"] == "lbracket" {
   760→      # 배열 접근 ([])
   761→      state = advance(state)
   762→      index = parseExpression(state)
   763→      state = index["_state"]
   764→
   765→      if currentToken(state)["type"] == "rbracket" {
   766→        state = advance(state)
   767→      }
   768→
   769→      expr = createArrayAccess(expr, index)
   770→    }
   771→    else if currentToken(state)["type"] == "dot" {
   772→      # 멤버 접근 (.)
   773→      state = advance(state)
   774→      propToken = currentToken(state)
   775→
   776→      if propToken["type"] == "identifier" {
   777→        propName = propToken["value"]
   778→        state = advance(state)
   779→        expr = createMemberAccess(expr, propName)
   780→      } else {
   781→        print("Expected property name after '.'")
   782→        break
   783→      }
   784→    }
   785→    else {
   786→      break
   787→    }
   788→  }
   789→
   790→  return { "_state": state, "result": expr }
   791→}
   792→
   793→# 기본 표현식
   794→fn parsePrimary(state: {}) {
   795→  token = currentToken(state)
   796→
   797→  # 숫자
   798→  if token["type"] == "number" {
   799→    state = advance(state)
   800→    return { "_state": state, "result": createLiteral(token["value"], "number") }
   801→  }
   802→  # 문자열
   803→  else if token["type"] == "string" {
   804→    state = advance(state)
   805→    return { "_state": state, "result": createLiteral(token["value"], "string") }
   806→  }
   807→  # true, false
   808→  else if token["type"] == "keyword" and (token["value"] == "true" or token["value"] == "false") {
   809→    state = advance(state)
   810→    return { "_state": state, "result": createLiteral(token["value"], "boolean") }
   811→  }
   812→  # null
   813→  else if token["type"] == "keyword" and token["value"] == "null" {
   814→    state = advance(state)
   815→    return { "_state": state, "result": createLiteral(null, "null") }
   816→  }
   817→  # 배열 리터럴 ([])
   818→  else if token["type"] == "lbracket" {
   819→    state = advance(state)
   820→    elements = []
   821→
   822→    while currentToken(state)["type"] != "rbracket" {
   823→      elem = parseExpression(state)
   824→      state = elem["_state"]
   825→      elements = elements + [elem]
   826→
   827→      if currentToken(state)["type"] == "comma" {
   828→        state = advance(state)
   829→      }
   830→    }
   831→
   832→    state = advance(state)  # rbracket
   833→    return { "_state": state, "result": createArrayLiteral(elements) }
   834→  }
   835→  # 딕셔너리 리터럴 ({})
   836→  else if token["type"] == "lbrace" {
   837→    state = advance(state)
   838→    pairs = []
   839→
   840→    while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   841→      # 키 (문자열 또는 식별자)
   842→      keyToken = currentToken(state)
   843→      let key = null
   844→
   845→      if keyToken["type"] == "string" {
   846→        key = keyToken["value"]
   847→        state = advance(state)
   848→      } else if keyToken["type"] == "identifier" {
   849→        key = keyToken["value"]
   850→        state = advance(state)
   851→      } else {
   852→        print("Expected key in dictionary literal")
   853→        break
   854→      }
   855→
   856→      # 콜론
   857→      if currentToken(state)["type"] != "colon" {
   858→        print("Expected ':' after dictionary key")
   859→        break
   860→      }
   861→      state = advance(state)
   862→
   863→      # 값
   864→      value = parseExpression(state)
   865→      state = value["_state"]
   866→
   867→      # 키-값 쌍 추가
   868→      pairs = pairs + [{ "key": key, "value": value }]
   869→
   870→      # 쉼표 또는 종료
   871→      if currentToken(state)["type"] == "comma" {
   872→        state = advance(state)
   873→      }
   874→      else if currentToken(state)["type"] == "rbrace" {
   875→        break
   876→      }
   877→    }
   878→
   879→    if currentToken(state)["type"] == "rbrace" {
   880→      state = advance(state)
   881→    }
   882→
   883→    return { "_state": state, "result": createDictLiteral(pairs) }
   884→  }
   885→  # 괄호 표현식
   886→  else if token["type"] == "lparen" {
   887→    state = advance(state)
   888→    expr = parseExpression(state)
   889→    state = expr["_state"]
   890→
   891→    if currentToken(state)["type"] == "rparen" {
   892→      state = advance(state)
   893→    }
   894→
   895→    return { "_state": state, "result": expr }
   896→  }
   897→  # 식별자
   898→  else if token["type"] == "identifier" {
   899→    state = advance(state)
   900→    return { "_state": state, "result": createIdentifier(token["value"]) }
   901→  }
   902→  else {
   903→    print("Unexpected token: " + token["type"])
   904→    return { "_state": state, "result": null }
   905→  }
   906→}
