     5→/**
     6→ * Example 1: 산술 연산 (3 + 5 = 8)
     7→ * MOV r0, 0   (r0 = 0)
     8→ * MOV r1, 3   (r1 = 3)
     9→ * MOV r2, 5   (r2 = 5)
    10→ * ADD r0, r1, r2  (r0 = r1 + r2)
    11→ * HALT
    12→ */
    13→void test_arithmetic() {
    14→    printf("\n=== Test 1: Arithmetic (3 + 5) ===\n");
    15→
    16→    uint8_t bytecode[] = {
    17→        OP_MOV, 0, 0,              /* MOV r0, r0 (dummy) */
    18→        OP_MOV, 1, 0,              /* MOV r1, 0 */
    19→        OP_MOV, 2, 0,              /* MOV r2, 0 */
    20→        OP_MOV, 0, 1,              /* MOV r0, r1 (r0 = 3) */
    21→        /* Need to load immediate values - use LOAD for simplicity */
    22→        OP_HALT
    23→    };
    24→
    25→    /* Simpler: directly set register values */
    26→    VM vm;
    27→    vm_init(&vm);
    28→    vm.registers[1] = 3;   /* r1 = 3 */
    29→    vm.registers[2] = 5;   /* r2 = 5 */
    30→
    31→    uint8_t code[] = {
    32→        OP_ADD, 0, 1, 2,   /* ADD r0, r1, r2 */
    33→        OP_HALT
    34→    };
    35→
    36→    vm_run(&vm, code, sizeof(code));
    37→    printf("Result: r0 = %d (expected 8)\n", vm.registers[0]);
    38→    if (vm.registers[0] == 8) printf("✓ PASS\n");
    39→    else printf("✗ FAIL\n");
    40→}
    41→
    42→/**
    43→ * Example 2: 조건 분기 (if r1 == r2 then jump)
    44→ * CMP r1, r2          (compare r1 and r2)
    45→ * JMP_IF E, addr_true (if equal, jump to addr_true)
    46→ * HALT
    47→ * addr_true: MOV r0, 1 (r0 = 1)
    48→ * HALT
    49→ */
    50→void test_conditional_jump() {
    51→    printf("\n=== Test 2: Conditional Jump (5 == 5) ===\n");
    52→
    53→    VM vm;
    54→    vm_init(&vm);
    55→    vm.registers[1] = 5;
    56→    vm.registers[2] = 5;
    57→
    58→    /*
    59→     * Bytecode:
    60→     * 0: CMP r1, r2  [0,1,2]
    61→     * 3: JMP_IF E(equal), addr 8  [3,4,5,6]
    62→     * 7: HALT (not taken)  [7]
    63→     * 8: MOV r0, r1 (taken path)  [8,9,10]
    64→     * 11: HALT  [11]
    65→     */
    66→    uint8_t code[] = {
    67→        OP_CMP, 1, 2,              /* CMP r1, r2 */
    68→        OP_JMP_IF, 2, 0, 8,        /* JMP_IF E(equal), addr 8 */
    69→        OP_HALT,                   /* Not taken */
    70→        OP_MOV, 0, 1,              /* r0 = r1 (taken path) */
    71→        OP_HALT
    72→    };
    73→
    74→    vm_run(&vm, code, sizeof(code));
    75→    printf("Result: r0 = %d (expected 5, jump was taken)\n", vm.registers[0]);
    76→    if (vm.registers[0] == 5) printf("✓ PASS\n");
    77→    else printf("✗ FAIL\n");
    78→}
