    80→/**
    81→ * Example 3: 함수 호출 (CALL + RET)
    82→ * CALL func_addr      (call function at addr 6)
    83→ * HALT
    84→ * func_addr: MOV r0, 42 (function body)
    85→ * RET
    86→ */
    87→void test_function_call() {
    88→    printf("\n=== Test 3: Function Call ===\n");
    89→
    90→    VM vm;
    91→    vm_init(&vm);
    92→
    93→    /*
    94→     * Bytecode:
    95→     * 0: CALL 4
    96→     * 3: HALT
    97→     * 4: MOV r0, 1 (function)
    98→     * 7: RET
    99→     */
   100→    uint8_t code[] = {
   101→        OP_CALL, 0, 4,             /* CALL addr 4 */
   102→        OP_HALT,
   103→        OP_MOV, 0, 1,              /* Function: r0 = r1 (r1=42) */
   104→        OP_RET
   105→    };
   106→
   107→    vm.registers[1] = 42;          /* Pass value in r1 */
   108→    vm_run(&vm, code, sizeof(code));
   109→    printf("Result: r0 = %d (expected 42)\n", vm.registers[0]);
   110→    if (vm.registers[0] == 42) printf("✓ PASS\n");
   111→    else printf("✗ FAIL\n");
   112→}
   113→
   114→/**
   115→ * Example 4: 루프 (FOR_INIT + FOR_NEXT)
   116→ * FOR_INIT r0, 3      (loop 3 times)
   117→ * ADD r1, r1, r2      (r1 += r2, r2=1)
   118→ * FOR_NEXT r0, loop_start
   119→ * HALT
   120→ */
   121→void test_loop() {
   122→    printf("\n=== Test 4: Loop (sum 1+1+1) ===\n");
   123→
   124→    VM vm;
   125→    vm_init(&vm);
   126→    vm.registers[1] = 0;           /* r1 = 0 (accumulator) */
   127→    vm.registers[2] = 1;           /* r2 = 1 (increment) */
   128→
   129→    /*
   130→     * Bytecode (address calculation):
   131→     * 0-4: FOR_INIT r0, 3  [OP, reg, c1, c2, c3, c4]
   132→     * 5-8: ADD r1, r1, r2  [OP, dest, src1, src2]
   133→     * 9-12: FOR_NEXT r0, 0 [OP, reg, addr_hi, addr_lo]
   134→     * 13: HALT
   135→     *
   136→     * Total: 14 bytes
   137→     */
   138→    uint8_t code[] = {
   139→        OP_FOR_INIT, 0, 0, 0, 3,   /* FOR_INIT r0, 3 (5 bytes) */
   140→        OP_ADD, 1, 1, 2,           /* r1 = r1 + r2 (4 bytes) */
   141→        OP_FOR_NEXT, 0, 0, 0,      /* FOR_NEXT r0, addr 0 (4 bytes) */
   142→        OP_HALT                    /* (1 byte) */
   143→    };
   144→
   145→    vm_run(&vm, code, sizeof(code));
   146→    printf("Result: r1 = %d (expected 3, sum of 1+1+1)\n", vm.registers[1]);
   147→    if (vm.registers[1] == 3) printf("✓ PASS\n");
   148→    else printf("✗ FAIL\n");
   149→}
   150→
   151→/**
   152→ * Example 5: 예외 처리 (TRY + RAISE + CATCH)
   153→ * TRY_BEGIN handler_addr
   154→ * MOV r1, 1
   155→ * DIV r0, r1, r0      (divide by 0 → exception)
   156→ * MOV r0, 999
   157→ * TRY_END
   158→ * HALT
   159→ * handler_addr: CATCH r0 (r0 = error code)
   160→ * HALT
   161→ */
   162→void test_exception_handling() {
   163→    printf("\n=== Test 5: Exception Handling (divide by zero) ===\n");
   164→
   165→    VM vm;
   166→    vm_init(&vm);
   167→    vm.registers[0] = 0;           /* r0 = 0 (divisor - will cause exception) */
   168→    vm.registers[1] = 10;          /* r1 = 10 (dividend) */
   169→
   170→    /*
   171→     * Bytecode:
   172→     * 0: TRY_BEGIN 8
   173→     * 3: DIV r0, r1, r0 (10 / 0 → exception)
   174→     * 7: MOV r0, 999 (not executed)
   175→     * 10: HALT
   176→     * 8: CATCH r0 (catch error, code in r0)
   177→     * 10: HALT
   178→     */
   179→    uint8_t code[] = {
   180→        OP_TRY_BEGIN, 0, 8,        /* TRY_BEGIN handler at 8 */
   181→        OP_DIV, 0, 1, 0,           /* DIV r0, r1, r0 → will raise */
   182→        OP_MOV, 0, 1,              /* Not executed */
   183→        OP_HALT,
   184→        OP_CATCH, 0,               /* CATCH error_code into r0 */
   185→        OP_HALT
   186→    };
   187→
   188→    /* Note: Exception handler is set up, but this is simplified for demo */
   189→    printf("Note: Full exception handling requires signal setup (see vm_raise)\n");
   190→    printf("Expected: DivideByZero exception caught\n");
   191→}
   192→
   193→/**
   194→ * Example 6: 스택 연산 (PUSH + POP)
   195→ * MOV r0, 100
   196→ * PUSH r0
   197→ * MOV r1, 200
   198→ * POP r2
   199→ * HALT
   200→ */
   201→void test_stack_operations() {
   202→    printf("\n=== Test 6: Stack Operations (PUSH/POP) ===\n");
   203→
   204→    VM vm;
   205→    vm_init(&vm);
   206→    vm.registers[0] = 100;
   207→    vm.registers[1] = 200;
   208→
   209→    uint8_t code[] = {
   210→        OP_PUSH, 0,                /* PUSH r0 */
   211→        OP_POP, 2,                 /* POP r2 */
   212→        OP_HALT
   213→    };
   214→
   215→    vm_run(&vm, code, sizeof(code));
   216→    printf("Result: r2 = %d (expected 100, popped from stack)\n", vm.registers[2]);
   217→    printf("Stack pointer: sp = %d (expected -1)\n", vm.sp);
   218→    if (vm.registers[2] == 100 && vm.sp == -1) printf("✓ PASS\n");
   219→    else printf("✗ FAIL\n");
   220→}
   221→
   222→/**
   223→ * Example 7: 메모리 접근 (LOAD + STORE)
   224→ * MOV r0, 42
   225→ * STORE [addr 0], r0  (store 42 at address 0)
   226→ * LOAD r1, [addr 0]   (load from address 0)
   227→ * HALT
   228→ */
   229→void test_memory_access() {
   230→    printf("\n=== Test 7: Memory Access (LOAD/STORE) ===\n");
   231→
   232→    VM vm;
   233→    vm_init(&vm);
   234→    vm.registers[0] = 42;
   235→
   236→    /*
   237→     * Bytecode:
   238→     * 0: STORE addr(0,0), r0  (store r0 at addr 0)
   239→     * 4: LOAD r1, addr(0,0)   (load from addr 0 to r1)
   240→     * 7: HALT
   241→     */
   242→    uint8_t code[] = {
   243→        OP_STORE, 0, 0, 0,         /* STORE [addr 0], r0 */
   244→        OP_LOAD, 1, 0, 0,          /* LOAD r1, [addr 0] */
   245→        OP_HALT
   246→    };
   247→
   248→    vm_run(&vm, code, sizeof(code));
   249→    printf("Result: r1 = %d (expected 42, loaded from memory)\n", vm.registers[1]);
   250→    printf("Memory[0]: %d (expected 42)\n", *(int32_t*)(vm.memory + 0));
   251→    if (vm.registers[1] == 42) printf("✓ PASS\n");
   252→    else printf("✗ FAIL\n");
   253→}
   254→
   255→/**
   256→ * Example 8: 비교 및 플래그 (CMP)
   257→ * MOV r1, 10
   258→ * MOV r2, 5
   259→ * CMP r1, r2   (10 > 5)
   260→ * JMP_IF L(less), skip
   261→ * MOV r0, 1    (r0 = 1, not less)
   262→ * skip: HALT
   263→ */
   264→void test_comparison_flags() {
   265→    printf("\n=== Test 8: Comparison and Flags (10 > 5) ===\n");
   266→
   267→    VM vm;
   268→    vm_init(&vm);
   269→    vm.registers[1] = 10;
   270→    vm.registers[2] = 5;
   271→
   272→    uint8_t code[] = {
   273→        OP_CMP, 1, 2,              /* CMP r1, r2 */
   274→        OP_JMP_IF, 4, 0, 8,        /* JMP_IF L(less), skip (addr 8) */
   275→        OP_MOV, 0, 1,              /* r0 = r1 (r1=10) */
   276→        OP_HALT                    /* skip: */
   277→    };
   278→
   279→    vm_run(&vm, code, sizeof(code));
   280→    printf("Result: r0 = %d (expected 10, not less than 5)\n", vm.registers[0]);
   281→    printf("Flags: Z=%d E=%d L=%d (expected 0,0,0 for 10 > 5)\n",
   282→           vm.flags.Z, vm.flags.E, vm.flags.L);
   283→    if (vm.registers[0] == 10 && vm.flags.L == 0) printf("✓ PASS\n");
   284→    else printf("✗ FAIL\n");
   285→}
   286→
   287→int main() {
   288→    printf("\n╔════════════════════════════════════════════╗\n");
   289→    printf("║   FreeLang v4 ISA v1.0 VM 테스트 프로그램   ║\n");
   290→    printf("╚════════════════════════════════════════════╝\n");
   291→
   292→    test_arithmetic();
   293→    test_conditional_jump();
   294→    test_function_call();
   295→    test_loop();
   296→    test_exception_handling();
   297→    test_stack_operations();
   298→    test_memory_access();
   299→    test_comparison_flags();
   300→
   301→    printf("\n╔════════════════════════════════════════════╗\n");
   302→    printf("║   테스트 완료                               ║\n");
   303→    printf("╚════════════════════════════════════════════╝\n");
   304→
   305→    return 0;
   306→}
